#include <bits/stdc++.h>
using namespace std;using Mat=vector<vector<long long>>;
Mat add(const Mat&a,const Mat&b,int sign=1){int n=a.size();Mat c(n,vector<long long>(n));for(int i=0;i<n;i++)for(int j=0;j<n;j++)c[i][j]=a[i][j]+sign*b[i][j];return c;}
Mat strassen(const Mat&a,const Mat&b){int n=a.size();if(n<=2){Mat c(n,vector<long long>(n));for(int i=0;i<n;i++)for(int k=0;k<n;k++)for(int j=0;j<n;j++)c[i][j]+=a[i][k]*b[k][j];return c;}int h=n/2;auto cut=[&](const Mat&m,int r,int c){Mat x(h,vector<long long>(h));for(int i=0;i<h;i++)for(int j=0;j<h;j++)x[i][j]=m[i+r][j+c];return x;};Mat a11=cut(a,0,0),a12=cut(a,0,h),a21=cut(a,h,0),a22=cut(a,h,h),b11=cut(b,0,0),b12=cut(b,0,h),b21=cut(b,h,0),b22=cut(b,h,h);Mat m1=strassen(add(a11,a22),add(b11,b22)),m2=strassen(add(a21,a22),b11),m3=strassen(a11,add(b12,b22,-1)),m4=strassen(a22,add(b21,b11,-1)),m5=strassen(add(a11,a12),b22),m6=strassen(add(a21,a11,-1),add(b11,b12)),m7=strassen(add(a12,a22,-1),add(b21,b22));Mat c(n,vector<long long>(n)),c11=add(add(add(m1,m4),m5,-1),m7),c12=add(m3,m5),c21=add(m2,m4),c22=add(add(add(m1,m2,-1),m3),m6);for(int i=0;i<h;i++)for(int j=0;j<h;j++)c[i][j]=c11[i][j],c[i][j+h]=c12[i][j],c[i+h][j]=c21[i][j],c[i+h][j+h]=c22[i][j];return c;}
int main(){int n;cout<<"Matrix dimension n (1..64): ";if(!(cin>>n)||n<1||n>64)return 1;int p=1;while(p<n)p*=2;Mat a(p,vector<long long>(p)),b=a;cout<<"Enter matrix A:\n";for(int i=0;i<n;i++)for(int j=0;j<n;j++)cin>>a[i][j];cout<<"Enter matrix B:\n";for(int i=0;i<n;i++)for(int j=0;j<n;j++)cin>>b[i][j];auto c=strassen(a,b);cout<<"Product:\n";for(int i=0;i<n;i++){for(int j=0;j<n;j++)cout<<c[i][j]<<" ";cout<<"\n";}}
